                  <FormFieldCol label="Sự kiện theo dõi (tùy chọn)">
                    <TreePicker
                      value={field.value ?? ""}
                      onChange={(v) => field.onChange(v ?? "")}
                      options={eventOptions}
                      placeholder="Chọn sự kiện"
