      if (isDev) return MOCK_YEAR_AVERAGES
      const payload = await api.http.get<unknown>(
        `/parent/my-students/averages/year/${encodeURIComponent(studentCode)}`
      )
      const envelope = payload as { data?: YearAverage[] }
      return envelope.data ?? []
    },
    enabled: open,
    staleTime: 5 * 60_000,
    retry: false,
  })

  const {
    data: termAverages,
    isLoading: isLoadingTerm,
  } = useQuery<TermAverage[]>({
    queryKey: ["student-averages", "terms", studentCode],
    queryFn: async () => {
      if (isDev) return MOCK_TERM_AVERAGES
      const payload = await api.http.get<unknown>(
        `/parent/my-students/averages/terms/${encodeURIComponent(studentCode)}`
      )
      const envelope = payload as { data?: TermAverage[] }
      return envelope.data ?? []
    },
    enabled: open,
    staleTime: 5 * 60_000,
    retry: false,
  })

  const {
    data: overallAverage,
  } = useQuery<OverallAverage>({
    queryKey: ["student-averages", "overall", studentCode],
    queryFn: async () => {
      if (isDev) return MOCK_OVERALL_AVERAGE
      const payload = await api.http.get<unknown>(
        `/parent/my-students/averages/overall/${encodeURIComponent(studentCode)}`
      )
      const envelope = payload as { data?: OverallAverage }
      return envelope.data ?? ({} as OverallAverage)
    },
    enabled: open,
    staleTime: 5 * 60_000,
    retry: false,
  })

  const resolvedDetailed = isDev ? MOCK_DETAILED_SCORES : detailedScores
  const resolvedYear = isDev ? MOCK_YEAR_AVERAGES : yearAverages
  const resolvedTerm = isDev ? MOCK_TERM_AVERAGES : termAverages
  const resolvedOverall = isDev ? MOCK_OVERALL_AVERAGE : overallAverage

  const overallGpa = resolvedOverall?.averageGatherScore10 ?? resolvedOverall?.averageScore10 ?? resolvedOverall?.averageGatherScore4 ?? resolvedOverall?.averageScore4 ?? null
  const passedSubjects = resolvedDetailed?.filter(
    (s) => s.mark10 != null && s.mark10 >= 5
  ).length ?? null
  const totalSubjects = resolvedDetailed?.length ?? null

  const isTenScale = resolvedOverall?.averageGatherScore10 != null || resolvedOverall?.averageScore10 != null
  const rank = overallGpa != null
    ? isTenScale
      ? overallGpa >= 8.0 ? "Giỏi" : overallGpa >= 6.5 ? "Khá" : overallGpa >= 5.0 ? "Trung bình" : "Yếu"
      : overallGpa >= 3.6 ? "Giỏi" : overallGpa >= 2.5 ? "Khá" : overallGpa >= 2.0 ? "Trung bình" : "Yếu"
    : null

  const statCards = [
    { label: "GPA tổng", value: overallGpa?.toFixed(2) ?? null, icon: Star, color: "text-emerald-600 dark:text-emerald-400", bg: "bg-emerald-50 dark:bg-emerald-950/20", iconBg: "bg-emerald-100 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-400" },
    { label: "Tín chỉ tích lũy", value: null, icon: BookCheck, color: "text-blue-600 dark:text-blue-400", bg: "bg-blue-50 dark:bg-blue-950/20", iconBg: "bg-blue-100 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400" },
    { label: "Môn đã đạt", value: passedSubjects != null ? `${passedSubjects}/${totalSubjects}` : null, icon: ScrollText, color: "text-purple-600 dark:text-purple-400", bg: "bg-purple-50 dark:bg-purple-950/20", iconBg: "bg-purple-100 dark:bg-purple-900/30 text-purple-600 dark:text-purple-400" },
    { label: "Xếp loại", value: rank, icon: Award, color: "text-amber-600 dark:text-amber-400", bg: "bg-amber-50 dark:bg-amber-950/20", iconBg: "bg-amber-100 dark:bg-amber-900/30 text-amber-600 dark:text-amber-400" },
  ]

  const showStats = overallGpa != null || passedSubjects != null

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-h-[90vh] max-w-7xl overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="text-xl">
            Kết quả học tập — <span className="font-bold">{studentName ?? studentCode}</span>
          </DialogTitle>
          {studentName && (
            <DialogDescription className="font-mono text-xs">{studentCode}</DialogDescription>
          )}
        </DialogHeader>

        {showStats && (
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
            {statCards.map((s) => {
              const Icon = s.icon
              return (
                <Card key={s.label} size="sm" className={cn("border-0", s.bg)}>
                  <CardHeader className="flex-row items-center gap-2 pb-1">
                    <div className={cn("flex size-6 items-center justify-center rounded", s.iconBg)}>
                      <Icon className="size-3.5" />
                    </div>
                    <CardTitle className="text-xs font-medium text-muted-foreground">{s.label}</CardTitle>
                  </CardHeader>
                  <CardContent className="pt-0">
                    <div className={cn("text-lg font-bold leading-tight tracking-tight", s.color)}>
                      {s.value ?? "—"}
                    </div>
                  </CardContent>
                </Card>
              )
            })}
          </div>
        )}

        <StudentScoresSection
          isActive={true}
          studentName={studentName}
          detailedScores={resolvedDetailed}
          isLoadingDetailed={isLoadingDetailed}
          yearAverages={resolvedYear}
          isLoadingYear={isLoadingYear}
          termAverages={resolvedTerm}
          isLoadingTerm={isLoadingTerm}
        />
      </DialogContent>
    </Dialog>
  )
}

function GradePanel({
  studentCode,
  studentName,
}: {
  studentCode: string
  studentName: string | null
}) {
  const [open, setOpen] = useState(false)
  return (
    <div className="mt-3">
      <Button
        variant="outline"
        size="sm"
        className="h-8 gap-1.5 text-xs"
        onClick={() => setOpen(true)}
      >
        <BarChart3 className="size-3.5" />
        Xem kết quả học tập
      </Button>
      <EnhancedGradeDialog
        studentCode={studentCode}
        studentName={studentName}
        open={open}
        onClose={() => setOpen(false)}
      />
    </div>
  )
}

function AddStudentDialog({
  open,
  onClose,
  onSuccess,
}: {
  open: boolean
  onClose: () => void
  onSuccess: () => void
}) {
  const [studentCode, setStudentCode] = useState("")
  const [studentName, setStudentName] = useState("")
  const [note, setNote] = useState("")
  const [error, setError] = useState("")

  const mutation = useMutation({
    mutationFn: async () => {
      const payload = await api.http.post<unknown>("/parent/my-students", {
        studentCode,
        studentName,
        note,
      })
      const envelope = payload as { success?: boolean; message?: string }
      if (envelope.success === false) throw new Error(envelope.message ?? "Lỗi")
      return payload
    },
    onSuccess: () => {
      setStudentCode("")
      setStudentName("")
      setNote("")
      setError("")
      onSuccess()
      onClose()
    },
    onError: (err) => {
      setError(err instanceof Error ? err.message : "Lỗi hệ thống")
    },
  })

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Plus className="size-5" />
            Thêm liên kết học sinh
          </DialogTitle>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="studentCode">
              Mã sinh viên <span className="text-rose-500">*</span>
            </Label>
            <Input
              id="studentCode"
              value={studentCode}
              onChange={(e) => setStudentCode(e.target.value)}
              placeholder="VD: SV2024001"
              autoFocus
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="studentName">Họ tên con</Label>
            <Input
              id="studentName"
              value={studentName}
              onChange={(e) => setStudentName(e.target.value)}
              placeholder="Nhập họ tên để dễ nhận diện"
            />
          </div>
          <div className="space-y-1.5">
            <Label htmlFor="note">Ghi chú</Label>
            <Input
              id="note"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder="Thông tin thêm cho quản trị viên"
            />
          </div>
          {error && (
            <p className="flex items-center gap-1.5 text-sm text-rose-600">
              <AlertCircle className="size-4" />
              {error}
            </p>
          )}
          <p className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-700 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-400">
            Yêu cầu sẽ chờ xác nhận từ quản trị viên trước khi hiển thị bảng
            điểm.
          </p>
        </div>
        <DialogFooter>
          <Button
            variant="outline"
            onClick={onClose}
            disabled={mutation.isPending}
          >
            Hủy
          </Button>
          <Button
            onClick={() => mutation.mutate()}
            disabled={!studentCode.trim() || mutation.isPending}
          >
            {mutation.isPending ? "Đang gửi…" : "Gửi yêu cầu"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

export default function MyStudentsPage() {
  const { user } = useAuth()
  const canCreate = user ? canUserAccess(user, PERMISSION_CODES.STUDENTS_CREATE) : false
  const canDelete = user ? canUserAccess(user, PERMISSION_CODES.STUDENTS_DELETE) : false
  const queryClient = useQueryClient()
  const [addOpen, setAddOpen] = useState(false)
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null)

  const { data: students, isLoading } = useQuery<ParentStudentRow[]>({
    queryKey: ["parent-students", "my"],
    queryFn: async () => {
      const payload = await api.http.get<unknown>("/parent/my-students")
      const envelope = payload as { data?: ParentStudentRow[] }
      return envelope.data ?? []
    },
    staleTime: 30_000,
  })

  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      await api.http.delete(`/parent/my-students/${id}`)
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({
        queryKey: ["parent-students", "my"],
      })
      setConfirmDeleteId(null)
    },
  })

  const displayName = user?.name?.trim() || user?.email || "Phụ huynh"

  return (
    <AdminPageGuard>
      <AdminPageSection>
      <AdminListPageHeader
        title="Quản lý sinh viên"
        subtitle={<>
          Xin chào,{" "}
          <span className="font-semibold text-foreground">{displayName}</span>
          . Quản lý liên kết sinh viên và theo dõi kết quả học tập.
        </>}
        icon={GraduationCap}
        actions={canCreate ? (
          <AdminPageHeaderPrimaryButton onClick={() => setAddOpen(true)}>
            <Plus className="size-4" />
            Thêm sinh viên
          </AdminPageHeaderPrimaryButton>
        ) : undefined}
      />

      {isLoading && (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {[1, 2, 3].map((i) => (
            <Card key={i}>
              <CardHeader className="pb-3">
                <Skeleton className="h-5 w-32" />
                <Skeleton className="h-4 w-20" />
              </CardHeader>
              <CardContent>
                <Skeleton className="h-8 w-full" />
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {!isLoading && (!students || students.length === 0) && (
        <Card className="py-10 text-center">
          <CardContent className="flex flex-col items-center gap-3">
            <div className="flex size-14 items-center justify-center rounded-full bg-muted/60">
              <GraduationCap className="size-7 text-muted-foreground" />
            </div>
            <div>
              <p className="font-semibold">Chưa có liên kết sinh viên nào</p>
              <p className="mt-1 text-sm text-muted-foreground">
                Nhấn &ldquo;Thêm sinh viên&rdquo; để gửi yêu cầu liên kết với mã sinh
                viên.
              </p>
            </div>
            {canCreate && (
              <Button
                onClick={() => setAddOpen(true)}
                size="sm"
                className="mt-1 gap-2"
              >
                <Plus className="size-4" />
                Thêm sinh viên
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      {process.env.NODE_ENV === "development" && (
        <div className="space-y-4">
          <div className="flex items-center gap-2 rounded-lg border border-dashed border-yellow-400 bg-yellow-50 px-4 py-3 text-sm text-yellow-700 dark:bg-yellow-950/20 dark:text-yellow-400">
            <BarChart3 className="size-4 shrink-0" />
            <span className="font-medium">Demo danh sách liên kết sinh viên</span>
            <span className="text-yellow-600/70">— Dữ liệu mẫu — nhấn &quot;Xem kết quả học tập&quot; để xem bảng điểm 3 tab</span>
          </div>
          <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
            {MOCK_STUDENTS.map((s) => (
              <DevStudentCard key={s.code} studentCode={s.code} studentName={s.name} />
            ))}
          </div>
        </div>
      )}

      {students && students.length > 0 && (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
          {students.map((s) => {
            const cfg = STATUS_CONFIG[s.status]
            const StatusIcon = cfg.icon
            return (
              <Card key={s.id} className="relative flex flex-col">
                <CardHeader className="pb-2">
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex items-center gap-3">
                      <div className="flex size-10 shrink-0 items-center justify-center rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400">
                        <GraduationCap className="size-5" />
                      </div>
                      <div>
                        <CardTitle className="text-base">
                          {s.studentName ?? s.studentCode}
                        </CardTitle>
                        {s.studentName && (
                          <CardDescription className="font-mono text-xs">
                            {s.studentCode}
                          </CardDescription>
                        )}
                      </div>
                    </div>
                    <Badge className={cfg.className} variant="secondary">
                      <StatusIcon className="mr-1 size-3" />
                      {cfg.label}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="flex-1 pt-0">
                  {s.note && (
                    <p className="mb-2 text-xs text-muted-foreground">
                      Ghi chú: {s.note}
                    </p>
                  )}
                  <p className="text-xs text-muted-foreground">
                    Yêu cầu:{" "}
                    {new Date(s.createdAt).toLocaleDateString("vi-VN", {
                      day: "2-digit",
                      month: "2-digit",
                      year: "numeric",
                    })}
                  </p>

                  {s.status === "approved" && (
                    <GradePanel
                      studentCode={s.studentCode}
                      studentName={s.studentName ?? null}
                    />
                  )}

                  {s.status === "pending" && (
                    <div className="mt-3 flex items-center gap-1.5 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-xs text-amber-700 dark:border-amber-800 dark:bg-amber-950/30 dark:text-amber-400">
                      <Clock className="size-3.5 shrink-0" />
                      Đang chờ quản trị viên xét duyệt
                    </div>
                  )}

                  {s.status === "rejected" && (
                    <div className="mt-3 flex items-center gap-1.5 rounded-lg border border-rose-200 bg-rose-50 px-3 py-2 text-xs text-rose-700 dark:border-rose-800 dark:bg-rose-950/30 dark:text-rose-400">
                      <XCircle className="size-3.5 shrink-0" />
                      Yêu cầu đã bị từ chối
                    </div>
                  )}

                  {(s.status === "pending" || s.status === "rejected") && canDelete && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="mt-3 h-7 gap-1 px-2 text-xs text-muted-foreground hover:text-rose-600"
                      onClick={() => setConfirmDeleteId(s.id)}
                    >
                      <Trash2 className="size-3.5" />
                      Xóa yêu cầu
                    </Button>
                  )}
                </CardContent>
              </Card>
            )
          })}
        </div>
      )}

      <AddStudentDialog
        open={addOpen}
        onClose={() => setAddOpen(false)}
        onSuccess={() =>
          queryClient.invalidateQueries({ queryKey: ["parent-students", "my"] })
        }
      />

      <Dialog
        open={!!confirmDeleteId}
        onOpenChange={() => setConfirmDeleteId(null)}
      >
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>Xác nhận xóa yêu cầu</DialogTitle>
          </DialogHeader>
          <p className="text-sm text-muted-foreground">
            Bạn chắc chắn muốn xóa yêu cầu liên kết sinh viên này? Thao tác không
            thể hoàn tác.
          </p>
          <DialogFooter>
            <Button variant="outline" onClick={() => setConfirmDeleteId(null)}>
              Hủy
            </Button>
            <Button
              variant="destructive"
              disabled={deleteMutation.isPending}
              onClick={() =>
                confirmDeleteId && deleteMutation.mutate(confirmDeleteId)
              }
            >
              {deleteMutation.isPending ? "Đang xóa…" : "Xóa"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </AdminPageSection>
    </AdminPageGuard>
  )
}

src/app/my-students/_component/detailed-.content:
"use client"

import { useMemo, useState } from "react"
import { type ColumnDef } from "@tanstack/react-table"
import { Loader2, ChevronDown, ChevronRight } from "lucide-react"
import { Badge } from "@ui/components/badge"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@ui/components/collapsible"
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@ui/components/select"
import { cn } from "@ui/lib/utils"
import { AdminDataTable } from "@ui/components/data-table"
import { buildAdminTableXlsxExport } from "@ui/components/admin"
import type { DetailedScore } from "@/types/student-scores"
import { formatScore, formatGrade } from "./score-utils"
import { ScrollArea } from "@ui/components/scroll-area"

interface Props {
  scores?: DetailedScore[]
  isLoading: boolean
}

function SubjectTable({ subjects }: { subjects: DetailedScore[] }) {
  const columns = useMemo<ColumnDef<DetailedScore>[]>(
    () => [
      {
        id: "subject",
        header: "Môn học",
        enableColumnFilter: false,
        accessorKey: "curriculumName",
        meta: {
          exportValue: (row: DetailedScore) =>
            `${row.curriculumName ?? ""} (${row.curriculumID ?? ""})`.trim(),
        },
        cell: ({ row }) => (
          <div>
            <div className="text-sm font-medium">{row.original.curriculumName}</div>
            <div className="text-xs text-muted-foreground">{row.original.curriculumID}</div>
          </div>
        ),
      },
      {
        id: "mark10",
        header: () => <div className="w-full text-center">Hệ 10</div>,
        enableColumnFilter: false,
        accessorKey: "mark10",
        cell: ({ row }) => {
          const f = formatScore(row.original.mark10, "10")
          return <div className={cn("w-full text-center tabular-nums", f.color)}>{f.text}</div>
        },
      },
      {
        id: "mark4",
        header: () => <div className="w-full text-center">Hệ 4</div>,
        enableColumnFilter: false,
        accessorKey: "mark4",
        cell: ({ row }) => {
          const f = formatScore(row.original.mark4, "4")
          return <div className={cn("w-full text-center tabular-nums", f.color)}>{f.text}</div>
        },
      },
      {
        id: "markLetter",
        header: () => <div className="w-full text-center">Điểm chữ</div>,
        enableColumnFilter: false,
        accessorKey: "markLetter",
        cell: ({ row }) => {
          const g = formatGrade(row.original.markLetter)
          return (
            <div className="flex justify-center">
              <Badge variant="outline" className={cn("px-1.5 py-0", g.color)}>{g.text}</Badge>
            </div>
          )
        },
      },
    ],
    []
  )

  if (!subjects.length)
    return (
      <p className="py-3 text-sm text-muted-foreground">Không có dữ liệu</p>
    )
  return (
    <AdminDataTable
      data={subjects}
      columns={columns}
      emptyLabel="Không có dữ liệu"
      manualFiltering
      xlsxExport={buildAdminTableXlsxExport("student-detailed-scores", {
        pageCount: subjects.length,
        total: subjects.length,
      })}
    />
  )
}

export const DetailedScoresList = ({ scores, isLoading }: Props) => {
  const [filterYear, setFilterYear] = useState("all")
  const [openTerms, setOpenTerms] = useState<Set<string>>(new Set())

  const years = useMemo(
    () =>
      scores
        ? [...new Set(scores.map((s) => s.yearStudy).filter(Boolean))]
            .sort()
            .reverse()
        : [],
    [scores]
  )

  const grouped = useMemo(() => {
    if (!scores) return {}
    const filtered =
      filterYear === "all"
        ? scores
        : scores.filter((s) => s.yearStudy === filterYear)
    const map: Record<string, Record<string, DetailedScore[]>> = {}
    filtered.forEach((s) => {
      const y = s.yearStudy || "Khác"
      const t = s.termID || "Khác"
      ;(map[y] ??= {})[t] ??= []
      map[y][t].push(s)
    })
    return map
  }, [scores, filterYear])

  if (isLoading) {
    return (
      <div className="flex justify-center py-8">
        <Loader2 className="size-5 animate-spin text-muted-foreground" />
      </div>
    )
  }
  if (!scores?.length) {
    return (
      <div className="py-8 text-center text-sm text-muted-foreground">
        Chưa có dữ liệu điểm chi tiết
      </div>
    )
  }

  return (
    <ScrollArea className="max-h-[50vh] space-y-3 overflow-y-auto">
      <div className="space-y-3">
        <Select
          value={filterYear}
          onValueChange={(v) => setFilterYear(v ?? "all")}
        >
          <SelectTrigger className="w-44">
            <SelectValue>
              {filterYear === "all" ? "Tất cả năm học" : filterYear}
            </SelectValue>
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">Tất cả năm học</SelectItem>
            {years.map((y) => (
              <SelectItem key={y} value={y}>
                {y}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {Object.keys(grouped).length === 0 ? (
          <div className="py-6 text-center text-sm text-muted-foreground">
            Không tìm thấy dữ liệu
          </div>
        ) : (
          Object.entries(grouped)
            .sort(([a], [b]) => b.localeCompare(a))
            .map(([year, terms]) => (
              <div key={year}>
                <div className="mb-1 text-sm font-semibold text-foreground">
                  Năm học {year}
                </div>
                {Object.entries(terms)
                  .sort(([a], [b]) => a.localeCompare(b))
                  .map(([term, subjects]) => {
                    const key = `${year}-${term}`
                    const toggleTerm = () =>
                      setOpenTerms((prev) => {
                        const next = new Set(prev)
                        if (next.has(key)) {
                          next.delete(key)
                        } else {
                          next.add(key)
                        }
                        return next
                      })
                    return (
                      <Collapsible
                        key={key}
                        open={openTerms.has(key)}
                        onOpenChange={toggleTerm}
                        className="mb-2"
                      >
                        <CollapsibleTrigger
                          className={cn(
                            "flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-sm",
                            openTerms.has(key)
                              ? "rounded-t-md bg-primary text-primary-foreground"
                              : "hover:bg-muted/80"
                          )}
                        >
                          {openTerms.has(key) ? (
                            <ChevronDown className="size-3.5 shrink-0" />
                          ) : (
                            <ChevronRight className="size-3.5 shrink-0" />
                          )}
                          <span>Học kỳ {term}</span>
                          <Badge
                            variant="secondary"
                            className="ml-auto text-xs"
                          >
                            {subjects.length} môn
                          </Badge>
                        </CollapsibleTrigger>
                        <CollapsibleContent className="px-1 pt-2">
                          <SubjectTable subjects={subjects} />
                        </CollapsibleContent>
                      </Collapsible>
                    )
                  })}
              </div>
            ))
        )}
      </div>
    </ScrollArea>
  )
}

