export type { RbacPermission, RbacRole } from "@workspace/api-client";

export const PERMISSION_GROUPS = [
  "users",
  "posts",
  "categories",
  "tags",
  "guides",
  "media",
  "settings",
] as const;

export type CreateRoleInput = {
  code: string;
  name: string;
  description?: string | null;
  permissionCodes: string[];
  isActive: boolean;
};

export type UpdateRoleInput = Partial<CreateRoleInput>;

src/app/rbac/_component/_alert-dialog/ro.content:
"use client";

import { useForm, Controller } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Loader2, Plus } from "lucide-react";
import { toast } from "sonner";
import { Button } from "@ui/components/button";
import { Checkbox } from "@ui/components/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@ui/components/dialog";
import { Input } from "@ui/components/input";
import { Label } from "@ui/components/label";
import { ScrollArea } from "@ui/components/scroll-area";
import { Textarea } from "@ui/components/textarea";
import { FieldError } from "@ui/components/field";
import type { RbacPermission } from "@workspace/api-client";
import type { CreateRoleInput, UpdateRoleInput } from "../types";

const schema = z.object({
  code: z.string().min(1, "Mã vai trò không được để trống").regex(/^[a-z_]+$/, "Chỉ chứa chữ thường và gạch dưới"),
  name: z.string().min(1, "Tên nội bộ không được để trống"),
  displayName: z.string().min(1, "Tên hiển thị không được để trống"),
  description: z.string().optional(),
  permissionCodes: z.array(z.string()).min(1, "Phải chọn ít nhất 1 quyền"),
});

type FormData = z.infer<typeof schema>;

export interface RoleDialogProps {
  open: boolean;
  onClose: () => void;
  role?: {
    id: number;
    code: string;
    name: string;
    description: string | null;
    permissions: string[];
  } | null;
  permissions: RbacPermission[];
}

export function RoleDialog({ open, onClose, role, permissions }: RoleDialogProps) {
  const isEdit = !!role;

  const form = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: {
      code: role?.code || "",
      name: role?.name || "",
      displayName: role?.name || "",
      description: role?.description || "",
      permissionCodes: role?.permissions || [],
    },
  });

  const handleSubmit = async (data: FormData) => {
    try {
      if (isEdit && role) {
        const updateData: UpdateRoleInput = {
          name: data.name,
          displayName: data.displayName,
          description: data.description,
          permissionCodes: data.permissionCodes,
        };
        // TODO: Implement API call when endpoint is available
        // await api.rbac.updateRole(role.id, updateData);
        console.log("Update role:", role.id, updateData);
        toast.success("Đã cập nhật vai trò thành công");
      } else {
        const createData: CreateRoleInput = {
          code: data.code,
          name: data.name,
          displayName: data.displayName,
          description: data.description,
          permissionCodes: data.permissionCodes,
        };
        // TODO: Implement API call when endpoint is available
        // await api.rbac.createRole(createData);
        console.log("Create role:", createData);
        toast.success("Đã tạo vai trò thành công");
      }
      onClose();
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Không lưu được vai trò");
    }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>{isEdit ? "Cập nhật vai trò" : "Tạo vai trò mới"}</DialogTitle>
          <DialogDescription>
            Thiết lập thông tin vai trò và chọn quyền hạn phù hợp.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-4 py-2">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label htmlFor="code">Mã vai trò</Label>
              <Controller
                name="code"
                control={form.control}
                render={({ field }) => (
                  <>
                    <Input
                      id="code"
                      {...field}
                      disabled={isEdit}
                      placeholder="content_editor"
                    />
                    <FieldError>{form.formState.errors.code?.message}</FieldError>
                  </>
                )}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="displayName">Tên hiển thị</Label>
              <Controller
                name="displayName"
                control={form.control}
                render={({ field }) => (
                  <>
                    <Input id="displayName" {...field} placeholder="Biên tập nội dung" />
                    <FieldError>{form.formState.errors.displayName?.message}</FieldError>
                  </>
                )}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="name">Tên nội bộ</Label>
            <Controller
              name="name"
              control={form.control}
              render={({ field }) => (
                <>
                  <Input id="name" {...field} placeholder="Biên tập nội dung" />
                  <FieldError>{form.formState.errors.name?.message}</FieldError>
                </>
              )}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Mô tả</Label>
            <Controller
              name="description"
              control={form.control}
              render={({ field }) => (
                <Textarea id="description" {...field} placeholder="Mô tả rõ vai trò này phục vụ bộ phận nào..." />
              )}
            />
          </div>

          <Controller
            name="permissionCodes"
            control={form.control}
            render={({ field: { value, onChange }, fieldState }) => (
              <div className="space-y-2">
                <Label>Quyền hạn *</Label>
                <ScrollArea className="max-h-[300px] rounded-lg border border-border p-3">
                  <div className="space-y-2">
                    {permissions.map((perm) => (
                      <div key={perm.code} className="flex items-center gap-3">
                        <Checkbox
                          checked={value.includes(perm.code)}
                          onCheckedChange={(checked) => {
                            if (checked) {
                              onChange([...value, perm.code]);
                            } else {
                              onChange(value.filter((c) => c !== perm.code));
                            }
                          }}
                        />
                        <div className="flex-1">
                          <div className="text-sm font-medium">{perm.name}</div>
                          <div className="text-xs text-muted-foreground font-mono">{perm.code}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
                {fieldState.error && <FieldError>{fieldState.error.message}</FieldError>}
              </div>
            )}
          />

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Hủy
            </Button>
            <Button type="submit" disabled={form.formState.isSubmitting}>
              {form.formState.isSubmitting ? (
                <>
                  <Loader2 className="size-4 animate-spin mr-2" />
                  Đang lưu...
                </>
              ) : (
                <>
                  <Plus className="size-4 mr-2" />
                  {isEdit ? "Lưu thay đổi" : "Tạo vai trò"}
                </>
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

src/app/rbac/_component/_form/role-form-.content:
"use client"

import { useMemo, useState } from "react"
import {
  CheckCircle2,
  KeyRound,
  Lock,
  ShieldHalf,
  Shield,
} from "lucide-react"
import { Checkbox } from "@ui/components/checkbox"
import { FieldError, FieldSet, FieldSetContent, FieldSectionLegend } from "@ui/components/field"
import { FormFieldCol } from "@ui/components/typing"
import { Input } from "@ui/components/input"
import { Switch } from "@ui/components/switch"
import { ScrollArea } from "@ui/components/scroll-area"
import { AdminFormLayout, AdminFormMain, AdminFormPageHeader, AdminFormSidebar } from "@ui/components/admin"
import { Controller, useWatch } from "react-hook-form"
import type { UseFormReturn } from "react-hook-form"
import type { RbacPermission } from "@workspace/api-client"
import type { RoleFormValues } from "../_hooks/use-role-form"
import {
  permissionGroupKey,
  permissionGroupLabelVi,
  permissionLabelVi,
} from "@/lib/permission-labels"

export interface RoleFormShellProps {
  isEdit: boolean
  form: UseFormReturn<RoleFormValues>
  permissions: RbacPermission[]
  onSubmit: () => Promise<void> | void
  onCancel: () => void
  submitting: boolean
}

export function RoleFormShell(props: RoleFormShellProps) {
  const { isEdit, form, permissions, onSubmit, onCancel, submitting } = props

  const [permissionSearch, setPermissionSearch] = useState("")
  const [showSelectedOnly, setShowSelectedOnly] = useState(false)

  const watchedPermissions =
    useWatch({ control: form.control, name: "permissions" }) ?? []

  const visiblePermissions = useMemo(() => {
    const q = permissionSearch.trim().toLowerCase()
    let filtered = permissions
    if (showSelectedOnly) {
      const selected = new Set(watchedPermissions)
      filtered = filtered.filter((p) => selected.has(p.code))
    }
    if (q) {
      filtered = filtered.filter((p) =>
        [p.code, permissionLabelVi(p.code), p.description ?? ""]
          .join(" ")
          .toLowerCase()
          .includes(q)
      )
    }
    return filtered
  }, [permissionSearch, permissions, showSelectedOnly, watchedPermissions])

  const permissionGroups = useMemo(() => {
    const buckets = new Map<string, RbacPermission[]>()
    for (const perm of visiblePermissions) {
      const key = permissionGroupKey(perm.code)
      const arr = buckets.get(key)
      if (arr) arr.push(perm)
      else buckets.set(key, [perm])
    }
    return Array.from(buckets.entries())
      .map(([key, items]) => ({
        key,
        label: permissionGroupLabelVi(key),
        items: [...items].sort((a, b) => a.code.localeCompare(b.code)),
      }))
      .sort((a, b) => a.key.localeCompare(b.key))
  }, [visiblePermissions])

  return (
    <>
      <AdminFormPageHeader
        title={isEdit ? "Sửa vai trò" : "Thêm vai trò mới"}
        subtitle="Thiết lập thông tin vai trò và chọn quyền hạn phù hợp."
        onBack={onCancel}
        formId="role-form"
        isEdit={isEdit}
        submitting={submitting}
        saveLabel={isEdit ? "Lưu thay đổi" : "Tạo vai trò"}
      />

      <AdminFormLayout
        id="role-form"
        onSubmit={(e) => { e.preventDefault(); void onSubmit() }}
      >
        <AdminFormMain>
            <FieldSet variant="section">
              <FieldSectionLegend
                icon={Shield}
                title="Thông tin vai trò"
                description="Mã vai trò, tên hiển thị và mô tả."
              />
              <FieldSetContent variant="section" className="space-y-4 pt-0">
                <div className="grid gap-4 md:grid-cols-2">
                  <Controller
                    name="code"
                    control={form.control}
                    render={({ field, fieldState }) => (
                      <FormFieldCol label="Mã vai trò" required>
                        <Input
                          id={isEdit ? "e-code" : "c-code"}
                          placeholder="content_editor"
                          value={field.value}
                          onChange={field.onChange}
                          onBlur={field.onBlur}
                          disabled={isEdit}
                          className={fieldState.error ? "border-destructive" : ""}
                        />
                        {fieldState.error && (
                          <FieldError>{fieldState.error.message}</FieldError>
                        )}
                      </FormFieldCol>
                    )}
                  />
                  <Controller
                    name="name"
                    control={form.control}
                    render={({ field, fieldState }) => (
                      <FormFieldCol label="Tên hiển thị" required>
                        <Input
                          id={isEdit ? "e-name" : "c-name"}
                          placeholder="Biên tập nội dung"
                          value={field.value}
                          onChange={field.onChange}
                          onBlur={field.onBlur}
                          className={fieldState.error ? "border-destructive" : ""}
                        />
                        {fieldState.error && (
                          <FieldError>{fieldState.error.message}</FieldError>
                        )}
                      </FormFieldCol>
                    )}
                  />
                </div>
                <Controller
                  name="description"
                  control={form.control}
                  render={({ field }) => (
                    <FormFieldCol label="Mô tả">
                      <textarea
                        id="role-description"
                        className="flex min-h-[80px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50"
                        placeholder="Mô tả rõ vai trò này phục vụ bộ phận nào..."
                        value={field.value ?? ""}
                        onChange={field.onChange}
                      />
                    </FormFieldCol>
                  )}
                />
              </FieldSetContent>
            </FieldSet>

            <FieldSet variant="section">
              <FieldSectionLegend
                icon={KeyRound}
                title="Quyền hạn"
                description={isEdit ? "Chọn quyền hạn cho vai trò (thay thế toàn bộ khi lưu)." : "Chọn quyền hạn cho vai trò mới."}
              />
              <FieldSetContent variant="section" className="space-y-4 pt-0">
                <div className="flex items-center justify-between gap-2">
                  <p className="text-xs text-muted-foreground">
                    Đã chọn {watchedPermissions.length}/{permissions.length}
                  </p>
                  <button
                    type="button"
                    onClick={() => setShowSelectedOnly((prev) => !prev)}
                    className="rounded-md border border-border px-2 py-1 text-xs hover:bg-muted"
                  >
                    {showSelectedOnly ? "Hiện tất cả" : "Chỉ đã chọn"}
                  </button>
                </div>
                <Controller
                  name="permissions"
                  control={form.control}
                  render={({ field: { value, onChange } }) => (
                    <div className="space-y-2">
                      <Input
                        value={permissionSearch}
                        onChange={(e) => setPermissionSearch(e.target.value)}
                        placeholder="Tìm quyền..."
                        className="h-9"
                      />
                      <ScrollArea className="h-[calc(100vh-520px)] rounded-lg border border-border/60 bg-muted/10">
                        <div className="space-y-3 p-3">
                          {permissionGroups.length === 0 ? (
                            <p className="py-8 text-center text-sm text-muted-foreground">
                              Không có quyền khớp tìm kiếm.
                            </p>
                          ) : (
                            permissionGroups.map((group) => {
                              const selectedInGroup = group.items.filter((p) =>
                                value.includes(p.code)
                              ).length
                              return (
                                <section
                                  key={group.key}
                                  className="overflow-hidden rounded-lg border border-border/50 bg-card shadow-sm"
                                >
                                  <header className="flex items-center justify-between gap-3 border-b border-border/50 bg-muted/25 px-3 py-2">
                                    <div className="flex min-w-0 items-center gap-2">
                                      <Checkbox
                                        checked={
                                          selectedInGroup === group.items.length &&
                                          group.items.length > 0
                                        }
                                        onCheckedChange={(checked) => {
                                          const codes = group.items.map((p) => p.code)
                                          onChange(
                                            checked === true
                                              ? [...new Set([...value, ...codes])]
                                              : value.filter((c) => !codes.includes(c))
                                          )
                                        }}
                                      />
                                      <div className="min-w-0">
                                        <p className="truncate font-mono text-[11px] font-semibold tracking-wide text-muted-foreground uppercase">
                                          {group.key}
                                        </p>
                                        <p className="truncate text-sm font-semibold text-foreground">
                                          {group.label}
                                        </p>
                                      </div>
                                    </div>
                                    <span className="rounded-md border border-border/60 bg-background/90 px-2 py-0.5 text-xs text-muted-foreground tabular-nums">
                                      {selectedInGroup}/{group.items.length}
                                    </span>
                                  </header>
                                  <div className="grid gap-1.5 p-2 sm:grid-cols-2 lg:grid-cols-3">
                                    {group.items.map((perm) => {
                                      const isSelected = value.includes(perm.code)
                                      return (
                                        <label
                                          key={perm.code}
                                          className={`flex cursor-pointer items-center gap-2 rounded-md border px-2.5 py-1.5 transition-colors ${
                                            isSelected
                                              ? "border-primary/40 bg-primary/5"
                                              : "border-border/60 bg-background/90 hover:border-border hover:bg-muted/30"
                                          }`}
                                        >
                                          <Checkbox
                                            checked={isSelected}
                                            onCheckedChange={(checked) => {
                                              onChange(
                                                checked === true
                                                  ? [...new Set([...value, perm.code])]
                                                  : value.filter((c) => c !== perm.code)
                                              )
                                            }}
                                          />
                                          <span className="min-w-0 leading-tight">
                                            <span className="block text-sm font-medium">
                                              {permissionLabelVi(perm.code)}
                                            </span>
                                            <span className="block truncate font-mono text-[11px] text-muted-foreground">
                                              {perm.code}
                                            </span>
                                          </span>
                                        </label>
                                      )
                                    })}
                                  </div>
                                </section>
                              )
                            })
                          )}
                        </div>
                      </ScrollArea>
                    </div>
                  )}
                />
              </FieldSetContent>
            </FieldSet>
          </AdminFormMain>

        <AdminFormSidebar>
            <FieldSet variant="section">
              <FieldSectionLegend
                icon={isEdit ? CheckCircle2 : Lock}
                title={isEdit ? "Trạng thái" : "Kích hoạt"}
                description={isEdit ? "Tắt để vô hiệu hoá vai trò này." : "Tắt để tạo vai trò ở trạng thái không hoạt động."}
              />
              <FieldSetContent variant="section" className="space-y-4 pt-0">
                <Controller
                  name="isActive"
                  control={form.control}
                  render={({ field }) => (
                    <div className="flex items-center justify-between rounded-lg border border-border px-4 py-3">
                      <div>
                        <p className="text-sm font-medium">
                          {field.value ? "Đang hoạt động" : "Đã khoá"}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          {field.value
                            ? "Vai trò có thể được gán cho người dùng"
                            : "Vai trò không thể được gán"}
                        </p>
                      </div>
                      <Switch
                        checked={field.value}
                        onCheckedChange={field.onChange}
                      />
                    </div>
                  )}
                />
              </FieldSetContent>
            </FieldSet>

            <FieldSet variant="section">
              <FieldSectionLegend
                icon={ShieldHalf}
                title="Tổng quan quyền"
                description={`${watchedPermissions.length} quyền được chọn.`}
              />
              <FieldSetContent variant="section" className="pt-0">
                <div className="space-y-2">
                  {watchedPermissions.length === 0 ? (
                    <p className="py-4 text-center text-xs text-muted-foreground">
                      Chưa có quyền nào được chọn.
                    </p>
                  ) : (
                    permissionGroups
                      .filter((group) =>
                        group.items.some((p) => watchedPermissions.includes(p.code))
                      )
                      .map((group) => {
                        const selectedInGroup = group.items.filter((p) =>
                          watchedPermissions.includes(p.code)
                        ).length
                        return (
                          <div
                            key={group.key}
                            className="flex items-center justify-between rounded-md border border-border/50 px-3 py-2"
                          >
                            <div className="min-w-0">
                              <p className="text-xs font-medium text-foreground">
                                {group.label}
                              </p>
                              <p className="font-mono text-[10px] text-muted-foreground uppercase">
                                {group.key}
                              </p>
                            </div>
                            <span className="shrink-0 rounded-md bg-primary/10 px-2 py-0.5 text-xs font-medium text-primary tabular-nums">
                              {selectedInGroup}
                            </span>
                          </div>
                        )
                      })
                  )}
                </div>
              </FieldSetContent>
            </FieldSet>
        </AdminFormSidebar>
      </AdminFormLayout>
    </>
  )
}

src/app/rbac/_component/_hooks/use-role-.content:
"use client"

import { useCallback } from "react"
import { useForm } from "react-hook-form"
import { zodResolver } from "@hookform/resolvers/zod"
import { z } from "zod"

export const roleFormSchema = z.object({
  code: z.string().min(1, "Mã vai trò không được để trống").regex(/^[a-z][a-z0-9_]*$/, "Chỉ chứa chữ thường, số và gạch dưới, bắt đầu bằng chữ"),
  name: z.string().min(1, "Tên hiển thị không được để trống"),
  description: z.string().optional().or(z.literal("")),
  isActive: z.boolean(),
  permissions: z.array(z.string()),
})

export type RoleFormValues = z.infer<typeof roleFormSchema>

export function useRoleForm() {

  const form = useForm<RoleFormValues>({
    resolver: zodResolver(roleFormSchema),
    defaultValues: {
      code: "",
      name: "",
      description: "",
      isActive: true,
      permissions: [],
    },
    mode: "onChange",
  })

  const resetForm = useCallback(() => {
    form.reset({
      code: "",
      name: "",
      description: "",
      isActive: true,
      permissions: [],
    })
  }, [form])

  const populateForm = useCallback((role: {
    code: string
    name: string
    description?: string | null
    isActive: boolean
    permissions: string[]
  }) => {
    form.reset({
      code: role.code,
      name: role.name,
      description: role.description ?? "",
      isActive: role.isActive,
      permissions: role.permissions,
    })
  }, [form])

  const togglePermission = useCallback((code: string, checked: boolean) => {
    const current = form.getValues("permissions")
    if (checked) {
      form.setValue("permissions", [...new Set([...current, code])], { shouldDirty: true })
    } else {
      form.setValue("permissions", current.filter((c) => c !== code), { shouldDirty: true })
    }
  }, [form])

  const getPayload = useCallback((): {
    code: string
    name: string
    description: string
    isActive: boolean
    permissions: string[]
  } => {
    const values = form.getValues()
    return {
      code: values.code.trim(),
      name: values.name.trim(),
      description: values.description?.trim() || "",
      isActive: values.isActive,
      permissions: values.permissions,
    }
  }, [form])

  return {
    form,
    resetForm,
    populateForm,
    togglePermission,
    getPayload,
  }
}

src/app/rbac/_component/_query/use-rbac-.content:
"use client"

import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query"
import { toast } from "sonner"
import { api } from "@/lib/api"
import type { CreateRoleInput, UpdateRoleInput } from "../types"

export type RoleRow = {
  id: string
  code: string
  name: string
  description: string | null
  permissions: string[]
  isActive: boolean
  createdAt: string | null
  updatedAt: string | null
  deletedAt: string | null
}

type ApiEnvelope<T> = {
  success?: boolean
  message?: string
  error?: string | null
  data?: T
}

function normalizePermissions(value: unknown): string[] {
  if (Array.isArray(value)) {
    if (value.length > 0 && typeof value[0] === "object" && value[0] !== null) {
      return value.map((p: Record<string, unknown>) => String(p.code ?? ""))
    }
    return value.map(String)
  }
  if (typeof value === "string") {
    if (value === "" || value === "null" || value === "undefined") return []
    try {
      const parsed = JSON.parse(value)
      return normalizePermissions(parsed)
    } catch {}
  }
  return []
}

function normalizeRole(raw: Record<string, unknown>): RoleRow {
  const perms = (normalizePermissions(raw.permissions).length > 0
    ? normalizePermissions(raw.permissions)
    : normalizePermissions(raw.permissionCodes).length > 0
      ? normalizePermissions(raw.permissionCodes)
      : normalizePermissions(raw.permissionsList).length > 0
        ? normalizePermissions(raw.permissionsList)
        : []
  )
  return {
    id: String(raw.id ?? ""),
    code: String(raw.name ?? ""),
    name: String(raw.displayName ?? raw.name ?? ""),
    description: (raw.description as string | null | undefined) ?? null,
    permissions: perms,
    isActive: Boolean(raw.isActive ?? true),
    createdAt: (raw.createdAt as string | null | undefined) ?? null,
    updatedAt: (raw.updatedAt as string | null | undefined) ?? null,
    deletedAt: (raw.deletedAt as string | null | undefined) ?? null,
  }
}

function unwrapEnvelope<T>(payload: unknown): T {
  if (!payload || typeof payload !== "object") return payload as T
  const envelope = payload as ApiEnvelope<T>
  if (envelope.success === false) {
    throw new Error(envelope.message || envelope.error || "Yêu cầu thất bại")
  }
  return "data" in envelope ? (envelope.data as T) : (payload as T)
}

export const rbacQueryKeys = {
  all: ["rbac"] as const,
  catalog: () => [...rbacQueryKeys.all, "catalog"] as const,
  detail: (id: string) => [...rbacQueryKeys.all, "detail", id] as const,
}

export function useRbacCatalog() {
  return useQuery({
    queryKey: rbacQueryKeys.catalog(),
    queryFn: async () => {
      const [roles, permissions] = await Promise.all([
        api.rbac.listRoles(),
        api.rbac.listPermissions(),
      ])
      return { roles, permissions }
    },
    staleTime: 5 * 60 * 1000,
  })
}

export function useRoleDetail(id: string) {
  return useQuery({
    queryKey: rbacQueryKeys.detail(id),
    queryFn: async () => {
      const payload = await api.http.get(`/admin/roles/${id}`)
      const data = unwrapEnvelope<Record<string, unknown>>(payload)
      return normalizeRole(data)
    },
    enabled: !!id,
  })
}

export function useCreateRoleMutation() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (data: CreateRoleInput) => {
      const payload = await api.http.post("/admin/roles", {
        name: data.code,
        displayName: data.name,
        description: data.description || null,
        permissions: data.permissionCodes,
        isActive: data.isActive ?? true,
      })
      const role = unwrapEnvelope<Record<string, unknown>>(payload)
      return normalizeRole(role)
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: rbacQueryKeys.catalog() })
      queryClient.invalidateQueries({ queryKey: ["rbac", "roles", "list"] })
      toast.success("Đã tạo vai trò thành công")
    },
    onError: (error: Error) => {
      toast.error(`Lỗi tạo vai trò: ${error.message}`)
    },
  })
}

export function useUpdateRoleMutation() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async ({ id, data }: { id: string; data: UpdateRoleInput }) => {
      const payload = await api.http.put(`/admin/roles/${id}`, {
        name: data.code,
        displayName: data.name,
        description: data.description || null,
        permissions: data.permissionCodes,
        isActive: data.isActive,
      })
      const role = unwrapEnvelope<Record<string, unknown>>(payload)
      return normalizeRole(role)
    },
    onSuccess: (_data, variables) => {
      queryClient.invalidateQueries({ queryKey: rbacQueryKeys.detail(variables.id) })
      queryClient.invalidateQueries({ queryKey: rbacQueryKeys.catalog() })
      queryClient.invalidateQueries({ queryKey: ["rbac", "roles", "list"] })
      toast.success("Đã cập nhật vai trò thành công")
    },
    onError: (error: Error) => {
      toast.error(`Lỗi cập nhật vai trò: ${error.message}`)
    },
  })
}

export function useDeleteRoleMutation() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (id: string) => {
      await api.http.post("/admin/roles/bulk", { action: "delete", ids: [id] })
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: rbacQueryKeys.catalog() })
      queryClient.invalidateQueries({ queryKey: ["rbac", "roles", "list"] })
      toast.success("Đã xóa vai trò thành công")
    },
    onError: (error: Error) => {
      toast.error(`Lỗi xóa vai trò: ${error.message}`)
    },
  })
}

