"use client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@ui/components/card";
import { FieldError } from "@ui/components/field";
import { Input } from "@ui/components/input";
import { FormFieldCol } from "@ui/components/typing";
import { SelectPicker, TreePicker, type SelectPickerOption } from "@ui/components/pickers";
import {
  AdminFormLayout,
  AdminFormMain,
  AdminFormPageHeader,
  AdminFormSidebar,
} from "@ui/components/admin";
import { Controller, type UseFormReturn } from "react-hook-form";
import { cn } from "@ui/lib/utils";
import { Hash, Monitor } from "lucide-react";
import type { ScreenFormValues } from "../types";
export interface ScreenFormShellProps { form: UseFormReturn<ScreenFormValues>; onSubmit: (v: ScreenFormValues) => Promise<void>; submitting: boolean; editingId: string | null; cameraOptions: SelectPickerOption[]; templateOptions: SelectPickerOption[]; onBack: () => void; onReset: () => void; }
export function ScreenFormShell({ form, onSubmit, submitting, editingId, cameraOptions, templateOptions, onBack, onReset }: ScreenFormShellProps) {
  const { control } = form;
  return (<>
    <AdminFormPageHeader
      title={editingId ? "Chỉnh sửa màn hình" : "Thêm màn hình"}
      subtitle="Quản lý màn hình."
      onBack={onBack}
      onReset={onReset}
      formId="screen-form"
      submitting={submitting}
      isEdit={!!editingId}
    />
    <AdminFormLayout id="screen-form" onSubmit={form.handleSubmit(onSubmit)}>
      <AdminFormMain>
          <Card className="border border-border/70 shadow-sm">
            <CardHeader className="pb-2"><CardTitle className="flex items-center gap-2 text-lg"><Monitor className="size-5 text-primary" /> Thông tin màn hình</CardTitle><CardDescription>Thông tin cơ bản của màn hình.</CardDescription></CardHeader>
            <CardContent className="space-y-4">
              <Controller name="name" control={control} render={({ field, fieldState }) => (<FormFieldCol label="Tên màn hình" required><Input placeholder="VD: Màn hình sảnh A" {...field} className={cn(fieldState.error && "border-destructive")} />{fieldState.error && <FieldError>{fieldState.error.message}</FieldError>}</FormFieldCol>)} />
              <div className="grid gap-4 sm:grid-cols-2">
                <Controller name="code" control={control} render={({ field }) => (<FormFieldCol label="Mã màn hình"><Input placeholder="SCR-001" {...field} /></FormFieldCol>)} />
                <Controller name="cameraId" control={control} render={({ field }) => (<FormFieldCol label="Camera"><SelectPicker value={field.value} onChange={(value) => { field.onChange(value); const s = cameraOptions.find(o => o.value === value); form.setValue("cameraName", s?.label ?? ""); }} options={cameraOptions} placeholder="Chọn camera" /></FormFieldCol>)} />
              </div>
              <Controller name="templateId" control={control} render={({ field }) => (<FormFieldCol label="Template"><SelectPicker value={field.value} onChange={(value) => { field.onChange(value); const s = templateOptions.find(o => o.value === value); form.setValue("templateName", s?.label ?? ""); }} options={templateOptions} placeholder="Chọn template" /></FormFieldCol>)} />
            </CardContent>
          </Card>
      </AdminFormMain>
      <AdminFormSidebar>
          <Card className="border border-border/70 shadow-sm">
            <CardHeader className="pb-2"><CardTitle className="flex items-center gap-2 text-lg text-muted-foreground"><Hash className="size-5" /> Trạng thái</CardTitle></CardHeader>
            <CardContent className="space-y-3">
              <Controller name="status" control={control} render={({ field }) => (<FormFieldCol label="Trạng thái"><TreePicker
                            value={String(field.value)}
                            onChange={(v) => field.onChange(v != null ? Number(v) : 1)}
                            options={[
                              { value: "1", label: "Hoạt động" },
                              { value: "0", label: "Khóa" },
                            ]}
                            placeholder="Chọn trạng thái"
                          /></FormFieldCol>)} />
            </CardContent>
          </Card>
      </AdminFormSidebar>
    </AdminFormLayout>
  </>);
}

src/app/screens/_component/_hooks/use-sc.content:
import { useCallback, useState } from "react";
import { useForm } from "react-hook-form";
import { toast } from "sonner";
import type { ScreenConfirmAction, ScreenFormValues } from "../types";
import { screenFormSchema } from "../types";
import { zodResolver } from "@hookform/resolvers/zod";
const EMPTY: ScreenFormValues = { name: "", code: "", cameraId: "", cameraName: "", templateId: "", templateName: "", status: 1 };
export function buildScreenPayload(v: ScreenFormValues) { return { name: v.name.trim(), code: v.code?.trim() || null, cameraId: v.cameraId?.trim() || null, cameraName: v.cameraName?.trim() || null, templateId: v.templateId?.trim() || null, templateName: v.templateName?.trim() || null, status: v.status }; }
export function useScreenForm() { const form = useForm<ScreenFormValues>({ resolver: zodResolver(screenFormSchema), defaultValues: EMPTY }); return { form, resetForm: useCallback(() => form.reset(EMPTY), [form]) }; }
export function useHandleConfirmAction(del: { mutateAsync: (id: string) => Promise<unknown> }, restore: { mutateAsync: (id: string) => Promise<unknown> }, purge: { mutateAsync: (id: string) => Promise<unknown> }, setConfirmAction: (v: ScreenConfirmAction | null) => void) { return useCallback(async ({ kind, row }: ScreenConfirmAction) => { try { if (kind === "delete") { await del.mutateAsync(row.id); toast.success(`Đã đưa «${row.name}» vào thùng rác`); } else if (kind === "restore") { await restore.mutateAsync(row.id); toast.success(`Đã khôi phục «${row.name}»`); } else { await purge.mutateAsync(row.id); toast.success(`Đã xóa vĩnh viễn «${row.name}»`); } } catch (e: unknown) { toast.error(e instanceof Error ? e.message : "Lỗi"); } finally { setConfirmAction(null); } }, [del, restore, purge, setConfirmAction]); }
export function useConfirmAction() { const [a, s] = useState<ScreenConfirmAction | null>(null); return { confirmAction: a, setConfirmAction: s }; }

src/app/screens/_component/_query/use-sc.content:
import { useQuery } from "@tanstack/react-query";
import type { StoreSyncSdk } from "@workspace/api-client";
import type { ScreenDetail, ScreenRow } from "../types";
export function useScreenDetailQuery(api: StoreSyncSdk, id: string) { return useQuery({ queryKey: ["screens", "detail", id], queryFn: () => api.screens.get<ScreenDetail>(id), enabled: !!id }); }
export function useScreensListQuery(api: StoreSyncSdk, enabled: boolean, filters?: Record<string, string>) { return useQuery({ queryKey: ["screens", "list", filters], queryFn: async () => { const items: ScreenRow[] = []; let page = 1, total = Infinity; while (items.length < total) { const r = await api.screens.list<ScreenRow>({ page, limit: 100, status: "active", ...filters }); items.push(...r.items); total = r.total; if (!r.items.length) break; page++; } return items; }, enabled }); }
export function useScreensTrashQuery({ api, trashPage, trashPageSize, debouncedTrashQ, enabled, filters }: { api: StoreSyncSdk; trashPage: number; trashPageSize: number; debouncedTrashQ: string; enabled: boolean; filters?: Record<string, string>; }) { return useQuery({ queryKey: ["screens", "trash", trashPage, trashPageSize, debouncedTrashQ, filters], enabled, queryFn: () => api.screens.list<ScreenRow>({ page: trashPage, limit: trashPageSize, search: debouncedTrashQ.trim() || undefined, status: "deleted", ...filters }) }); }

