                        }}
                      />
                    </div>
                    <div className="flex w-full flex-col gap-2.5">
                      <Controller
                        name="avatar"
                        control={control}
                        render={({ field }) => (
                          <div className="min-w-0 flex-1 space-y-1">
                            <p className="text-xs text-muted-foreground">
